<template><transition name="fade"><div v-if="visible" class="fixed inset-0 z-[100] grid place-items-center bg-black/50 p-5"><section class="w-fit max-w-[calc(100vw-2.5rem)] rounded-2xl border border-yellow-400 bg-yellow-600/95 p-5 text-black shadow-2xl"><p class="font-bold">{{ message }}</p><div v-if="confirmText" class="mt-4 flex justify-end gap-2"><button class="rounded-lg bg-black/10 px-3 py-2 text-sm font-bold" @click="close">{{ cancelText }}</button><button class="rounded-lg bg-red-600 px-3 py-2 text-sm font-bold text-white" @click="confirm">{{ confirmText }}</button></div><button v-else class="mt-3 text-sm font-bold underline" @click="close">關閉</button></section></div></transition></template>
<script setup lang="ts">import { ref } from 'vue'; const props=defineProps<{message:string;confirmText?:string;cancelText?:string;onConfirm?:()=>void;onClose?:()=>void}>();const visible=ref(true);function close(){visible.value=false;setTimeout(()=>props.onClose?.(),250)}function confirm(){props.onConfirm?.();close()}</script>
<style scoped>.fade-enter-active,.fade-leave-active{transition:opacity .25s}.fade-enter-from,.fade-leave-to{opacity:0}</style>
